ange=e=> e.target.files[0] && loadImageFromFile(e.target.files[0]); $('borderFile').onchange=e=>{ const f=e.target.files[0]; if(!f) return; const rd=new FileReader(); rd.onload=()=>{ try{ const obj=JSON.parse(rd.result); const borders=parseBordersJSON(obj); const geoFeatures=parseGeoJSONFeatures(obj); let messages=[]; if(borders.length){ state.borders=borders; state.selectedBorderId=borders[0].id; updateBorderSelect(); messages.push(`${borders.length} area polygon(s)`); } if(geoFeatures.length){ state.geoFeatures=geoFeatures; state.selectedGeoFeatureId=null; state.hoveredGeoFeatureId=null; messages.push(`${geoFeatures.length} highlightable GeoJSON location(s)`); } redrawOverlay(); setStatus(messages.length ? `Imported ${messages.join(' and ')}.` : 'No supported area polygons or GeoJSON features found in JSON.'); }catch(err){ setStatus('Could not parse JSON: '+err.message); } }; rd.readAsText(f); }; $('sampleBtn').onclick=createSampleMap; $('clearBtn').onclick=()=>location.reload(); $('fitBtn').onclick=fitMap; $('drawBorderBtn').onclick=()=>{ state.drawing=true; state.drawPoints=[]; setStatus('Drawing area: click around the location boundary, then Close area.'); redrawOverlay(); }; $('closeBorderBtn').onclick=()=>{ if(state.drawPoints.length>=3){ const pts=[...state.drawPoints]; if(pts[0][0]!==pts.at(-1)[0]||pts[0][1]!==pts.at(-1)[1]) pts.push(pts[0]); const name=$('borderName').value||`Location Area ${state.nextBorderId}`; const b={id:state.nextBorderId++, name, points:pts}; state.borders.push(b); state.selectedBorderId=b.id; updateBorderSelect(); } state.drawing=false; state.drawPoints=[]; redrawOverlay(); }; $('deleteBorderBtn').onclick=()=>{ state.borders=state.borders.filter(b=>b.id!==state.selectedBorderId); state.selectedBorderId=state.borders[0]?.id||null; updateBorderSelect(); redrawOverlay(); }; $('borderSelect').onchange=e=>{ state.selectedBorderId=Number(e.target.value); redrawOverlay(); }; $('autoPaletteBtn').onclick=autoPalette; $('scanBtn').onclick=sca